(5155426, 749318, 79602, '<td valign="top">This is a really great composition with wonderful reflections.  It all blends so well!</td>', 'This is a really great composition with wonderful reflections.  It all blends so well!', '2008-12-28 20:41:51.000000', NULL, 1),
(5155604, 749613, 102031, '<td valign="top">I''m not sure if this fits in this challenge, but I do like the colors.</td>', 'I''m not sure if this fits in this challenge, but I do like the colors.', '2008-12-28 22:23:56.000000', NULL, 1),
(5155608, 748259, 102031, '<td valign="top">I like it (especially with the title).  The color scheme in particular is nice.</td>', 'I like it (especially with the title).  The color scheme in particular is nice.', '2008-12-28 22:24:49.000000', NULL, 1),
(5155611, 748758, 102031, '<td valign="top">I can''t really describe it, but I really like the layout of this picture.</td>', 'I can''t really describe it, but I really like the layout of this picture.', '2008-12-28 22:25:56.000000', NULL, 1),
(5155613, 749611, 102031, '<td valign="top">This one has a nice almost old-fashioned feel to it.</td>', 'This one has a nice almost old-fashioned feel to it.', '2008-12-28 22:26:20.000000', NULL, 1),
(5155616, 749655, 102031, '<td valign="top">This definitely brings up a lot of feelings of Christmas.  The lights make it even more festive and almost feel warm.</td>', 'This definitely brings up a lot of feelings of Christmas.  The lights make it even more festive and almost feel warm.', '2008-12-28 22:26:58.000000', NULL, 1),
(5155619, 749007, 102031, '<td valign="top">I love the expression on her face.</td>', 'I love the expression on her face.', '2008-12-28 22:28:16.000000', NULL, 1),
(5155620, 749518, 102031, '<td valign="top">Like the title suggests, I do like the geometry and symmetry (more or less) in this picture.</td>', 'Like the title suggests, I do like the geometry and symmetry (more or less) in this picture.', '2008-12-28 22:29:42.000000', NULL, 1),
(5155624, 748650, 102031, '<td valign="top">I like this one.  Is that a mannequin or real person standing behind the tree?</td>', 'I like this one.  Is that a mannequin or real person standing behind the tree?', '2008-12-28 22:31:57.000000', NULL, 1),
(5155626, 748377, 102031, '<td valign="top">I like this one, but the lights (a reflection, I''m assuming) are more a touch distracting.</td>', 'I like this one, but the lights (a reflection, I''m assuming) are more a touch distracting.', '2008-12-28 22:33:21.000000', NULL, 1),
(5155629, 749012, 102031, '<td valign="top">It took me a bit to figure out what I was looking at, but if I''m correct, this is a really interesting shot.</td>', 'It took me a bit to figure out what I was looking at, but if I''m correct, this is a really interesting shot.', '2008-12-28 22:36:39.000000', NULL, 1),
(5155632, 749287, 102031, '<td valign="top">I like the colors...</td>', 'I like the colors...', '2008-12-28 22:38:22.000000', NULL, 1),
(5155640, 749452, 102031, '<td valign="top">The snow created an interesting effect... I wish we had snow here, instead of 50+ degree weather.</td>', 'The snow created an interesting effect... I wish we had snow here, instead of 50+ degree weather.', '2008-12-28 22:44:25.000000', NULL, 1),
(5155650, 748752, 102031, '<td valign="top">I like how you layed this out / how it just happened to be, whichever the case may be...</td>', 'I like how you layed this out / how it just happened to be, whichever the case may be...', '2008-12-28 22:52:34.000000', NULL, 1),
(5155653, 749423, 102031, '<td valign="top">I really like this picture, especially the coloring and layout.</td>', 'I really like this picture, especially the coloring and layout.', '2008-12-28 22:54:46.000000', NULL, 1),
(5155656, 749318, 102031, '<td valign="top">The reflects seem to go between being intriguing and distracting, but that might just be me.  I like it in either case.</td>', 'The reflects seem to go between being intriguing and distracting, but that might just be me.  I like it in either case.', '2008-12-28 22:57:35.000000', NULL, 1),
(5155661, 748362, 102031, '<td valign="top">This reminds me of Fred and/or the lady from the video store from I Am Legend for some reason or another...</td>', 'This reminds me of Fred and/or the lady from the video store from I Am Legend for some reason or another...', '2008-12-28 23:01:43.000000', NULL, 1),
(5155662, 749558, 102031, '<td valign="top">And a giant bow on top...<br/> <br/>I like it.</td>', 'And a giant bow on top... I like it.', '2008-12-28 23:03:08.000000', NULL, 1),
(5155665, 749442, 102031, '<td valign="top">And the picture isn''t half bad either.</td>', 'And the picture isn''t half bad either.', '2008-12-28 23:05:56.000000', NULL, 1),
(5155670, 749551, 102031, '<td valign="top">I may be missing something, but that doesn''t quite look real... It''s a cool effect in either case.</td>', 'I may be missing something, but that doesn''t quite look real... It''s a cool effect in either case.', '2008-12-28 23:13:30.000000', NULL, 1),
(5155673, 748379, 102031, '<td valign="top">I really like the coloring on this one.  It''s a bit hard to follow because of some of the reflections, but that also lends to the charm.</td>', 'I really like the coloring on this one.  It''s a bit hard to follow because of some of the reflections, but that also lends to the charm.', '2008-12-28 23:18:25.000000', NULL, 1),
(5155693, 749558, 83313, '<td valign="top">Just comes off to me as a snapshot, I''m afraid. Composition just seems odd to me.</td>', 'Just comes off to me as a snapshot, I''m afraid. Composition just seems odd to me.', '2008-12-28 23:30:57.000000', NULL, 1),
(5155695, 749183, 83313, '<td valign="top">What is "low mileage" for a 40 year old car?</td>', 'What is "low mileage" for a 40 year old car?', '2008-12-28 23:32:40.000000', NULL, 1),
(5155714, 749609, 83313, '<td valign="top">Now that''s different.</td>', 'Now that''s different.', '2008-12-28 23:41:04.000000', NULL, 1),
(5155719, 748478, 83313, '<td valign="top">This looks familiar. I think this is a location I''ve seen in a few previous challenge entries. Pretty neat looking display.</td>', 'This looks familiar. I think this is a location I''ve seen in a few previous challenge entries. Pretty neat looking display.', '2008-12-28 23:43:22.000000', NULL, 1),
(5155724, 749614, 83313, '<td valign="top">Why lie about it?</td>', 'Why lie about it?', '2008-12-28 23:44:21.000000', NULL, 1),
(5155729, 748966, 83313, '<td valign="top">I like the fun scene you tried to capture through the window, I''m afraid it does not work for me though. The elements of the foreground seem to interfere with viewing the scene beyond, rather than enhancing and framing it.</td>', 'I like the fun scene you tried to capture through the window, I''m afraid it does not work for me though. The elements of the foreground seem to interfere with viewing the scene beyond, rather than enhancing and framing it.', '2008-12-28 23:46:50.000000', NULL, 1),
(5155733, 748904, 83313, '<td valign="top">When he grows up he''s going to wear a watch? Oh, an <b>expensive</b> watch!</td>', 'When he grows up he''s going to wear a watch? Oh, an expensive watch!', '2008-12-28 23:47:58.000000', NULL, 1),
(5155739, 749655, 83313, '<td valign="top">Ah, yes one of these under the tree would be great.</td>', 'Ah, yes one of these under the tree would be great.', '2008-12-28 23:50:36.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5155821, 749423, 11078, '<td valign="top">I gave you a 10<br/>Beautiful image with warmth and colour very nice Good luck</td>', 'I gave you a 10Beautiful image with warmth and colour very nice Good luck', '2008-12-29 00:22:35.000000', NULL, 1),
(5155822, 749496, 11078, '<td valign="top">Nicely done 9</td>', 'Nicely done 9', '2008-12-29 00:22:55.000000', NULL, 1),
(5155825, 748259, 11078, '<td valign="top">Nice detail and good overall image well done 9</td>', 'Nice detail and good overall image well done 9', '2008-12-29 00:23:25.000000', NULL, 1),
(5155968, 749280, 18450, '<td valign="top">Wonderful colours and expression on her face.</td>', 'Wonderful colours and expression on her face.', '2008-12-29 02:49:19.000000', NULL, 1),
(5155969, 749611, 18450, '<td valign="top">Wonderful details in this beautifully traditional Christmas shot.</td>', 'Wonderful details in this beautifully traditional Christmas shot.', '2008-12-29 02:51:00.000000', NULL, 1),
(5156004, 748259, 93407, '<td valign="top">Great composition &amp; lighting; really like the overall mood of this shot.</td>', 'Great composition & lighting; really like the overall mood of this shot.', '2008-12-29 03:58:52.000000', NULL, 1),
(5156085, 749183, 15711, '<td valign="top">That has to be california.  Love the bug.  Learned to drive on a similar 64 model.</td>', 'That has to be california.  Love the bug.  Learned to drive on a similar 64 model.', '2008-12-29 08:14:33.000000', NULL, 1),
(5156086, 749318, 15711, '<td valign="top">Love the Lennon portrait. That''s one I''ve not seen. :~)</td>', 'Love the Lennon portrait. That''s one I''ve not seen. :~)', '2008-12-29 08:15:08.000000', NULL, 1),
(5156087, 749545, 15711, '<td valign="top">Looks like Linen''s ''N Things. We have the same look here too. I''m always sad to see a business fail.</td>', 'Looks like Linen''s ''N Things. We have the same look here too. I''m always sad to see a business fail.', '2008-12-29 08:15:55.000000', NULL, 1),
(5156172, 749593, 63244, '<td valign="top">The way this is framed, it almost looks like an advertisement of old! Colors are marvelous! Very crisp focus. I like the hint of reflection in the window tops.</td>', 'The way this is framed, it almost looks like an advertisement of old! Colors are marvelous! Very crisp focus. I like the hint of reflection in the window tops.', '2008-12-29 09:44:19.000000', NULL, 1),
(5156174, 748402, 63244, '<td valign="top">The idea and the conversion are great. You needed to tip your camera just a hair to line up the right window edge a little better. (Neither side is lined up.) :)<br/>The lights(?) above each window add interest and I like the shadow from the roof line. The tonal range is quite good. All in all, it''s very clean and nicely done.</td>', 'The idea and the conversion are great. You needed to tip your camera just a hair to line up the right window edge a little better. (Neither side is lined up.) :)The lights(?) above each window add interest and I like the shadow from the roof line. The tonal range is quite good. All in all, it''s very clean and nicely done.', '2008-12-29 09:47:56.000000', NULL, 1),
(5156176, 749611, 63244, '<td valign="top">Beautiful and well suited for b&amp;w and for the challenge.  Very interesting to look at as there is so much to see, but that is appealing here. Love the different reflections caught in the upstairs windows. Nice detail and focus. The right side of the step is very dark for some reason. I really like this!</td>', 'Beautiful and well suited for b&w and for the challenge.  Very interesting to look at as there is so much to see, but that is appealing here. Love the different reflections caught in the upstairs windows. Nice detail and focus. The right side of the step is very dark for some reason. I really like this!', '2008-12-29 09:50:46.000000', NULL, 1),
(5156180, 748966, 63244, '<td valign="top">The shot idea is good, but those hanging stars are distracting to me. It''s very difficult to light evenly with natural light, thus might try an ND filter if you can. I cannot see that sweet childs face and they look to be having fun!!:) A lower angle would give you a subtle view of the stars and a better view of the outdoor activity.</td>', 'The shot idea is good, but those hanging stars are distracting to me. It''s very difficult to light evenly with natural light, thus might try an ND filter if you can. I cannot see that sweet childs face and they look to be having fun!!:) A lower angle would give you a subtle view of the stars and a better view of the outdoor activity.', '2008-12-29 09:55:30.000000', NULL, 1),
(5156182, 748478, 63244, '<td valign="top">Colors are quite nice on this. The different textures work as well.</td>', 'Colors are quite nice on this. The different textures work as well.', '2008-12-29 09:57:09.000000', NULL, 1),
(5156185, 749589, 63244, '<td valign="top">This has a beautifully nostalgic feel. the subtle light on the statues in front also add interest. colors are excellent. nicely done!! Tack sharp focus, too!</td>', 'This has a beautifully nostalgic feel. the subtle light on the statues in front also add interest. colors are excellent. nicely done!! Tack sharp focus, too!', '2008-12-29 09:59:54.000000', NULL, 1),
(5156188, 749389, 63244, '<td valign="top">I''m think headed I guess. struggling to see the challenge connection visually or from the title. Sorry! As for the photo, the treatment and perspective are interesting.</td>', 'I''m think headed I guess. struggling to see the challenge connection visually or from the title. Sorry! As for the photo, the treatment and perspective are interesting.', '2008-12-29 10:01:56.000000', NULL, 1),
(5156191, 749558, 63244, '<td valign="top">Can you afford $15K for an oil change??!! (I''m photographing the WRONG stuff, lol!)</td>', 'Can you afford $15K for an oil change??!! (I''m photographing the WRONG stuff, lol!)', '2008-12-29 10:03:15.000000', NULL, 1),
(5156192, 749474, 63244, '<td valign="top">Love the b&amp;w. great detail in the shot and I love the contrast of size here. water adds interest and helps draw you to the larger subject. Boarder here is useful. Nicely done!</td>', 'Love the b&w. great detail in the shot and I love the contrast of size here. water adds interest and helps draw you to the larger subject. Boarder here is useful. Nicely done!', '2008-12-29 10:05:10.000000', NULL, 1),
(5156196, 748650, 63244, '<td valign="top">the subtle lines work here. focus looks a hair soft to me.</td>', 'the subtle lines work here. focus looks a hair soft to me.', '2008-12-29 10:06:42.000000', NULL, 1),
(5156199, 749055, 63244, '<td valign="top">The reflection in the window makes the toys stand out! as this is basic editing...how in the world did you keep yourself out of the shot!! :)</td>', 'The reflection in the window makes the toys stand out! as this is basic editing...how in the world did you keep yourself out of the shot!! :)', '2008-12-29 10:08:49.000000', NULL, 1),
(5156200, 749483, 63244, '<td valign="top">Ok, now I want candy..........</td>', 'Ok, now I want candy..........', '2008-12-29 10:09:19.000000', NULL, 1),
(5156203, 749339, 63244, '<td valign="top">Love the colors.  not sure about the perspective. It''s interesting...</td>', 'Love the colors.  not sure about the perspective. It''s interesting...', '2008-12-29 10:10:22.000000', NULL, 1),
(5156204, 749551, 63244, '<td valign="top">The mural makes the model stand out. Cute take on the challenge. Great focus and colors.</td>', 'The mural makes the model stand out. Cute take on the challenge. Great focus and colors.', '2008-12-29 10:11:39.000000', NULL, 1),
(5156205, 748542, 63244, '<td valign="top">For me, it''s difficult to see what is in the window. LOTS going on here. :)</td>', 'For me, it''s difficult to see what is in the window. LOTS going on here. :)', '2008-12-29 10:12:58.000000', NULL, 1),
(5156208, 749613, 63244, '<td valign="top">I WANT ONE................<br/> <br/>Perhaps drop the exposure a quarter stop if possible. It''s really bright!! And I mean light wise, not color or style! :P  Title is hilarious!</td>', 'I WANT ONE................ Perhaps drop the exposure a quarter stop if possible. It''s really bright!! And I mean light wise, not color or style! :P  Title is hilarious!', '2008-12-29 10:14:59.000000', NULL, 1),
(5156211, 749442, 63244, '<td valign="top">Clean, simple, great color and style...and the photo is great, too! :P</td>', 'Clean, simple, great color and style...and the photo is great, too! :P', '2008-12-29 10:15:49.000000', NULL, 1),
(5156215, 748777, 63244, '<td valign="top">Is THAT Vicky''s.....lol!<br/>The focal point seems to be the image on the back of the shirt. Maybe a smaller DOF to deminish the shirt artwork or have the model wear a different shirt, lol. I like the focus on the poster and the baby doll. Shorter DOF would make it a it more seductive IMHO. The colors are really nice.</td>', 'Is THAT Vicky''s.....lol!The focal point seems to be the image on the back of the shirt. Maybe a smaller DOF to deminish the shirt artwork or have the model wear a different shirt, lol. I like the focus on the poster and the baby doll. Shorter DOF would make it a it more seductive IMHO. The colors are really nice.', '2008-12-29 10:20:03.000000', NULL, 1),
(5156218, 749452, 63244, '<td valign="top">Love this! The stop action of the snow only makes you want to "come closer" to see what''s actually in the window. Border works.</td>', 'Love this! The stop action of the snow only makes you want to "come closer" to see what''s actually in the window. Border works.', '2008-12-29 10:21:14.000000', NULL, 1),
(5156220, 749605, 63244, '<td valign="top">Interesting shot. Very clean and simple. I like the subtle border.</td>', 'Interesting shot. Very clean and simple. I like the subtle border.', '2008-12-29 10:22:01.000000', NULL, 1),
(5156223, 749636, 63244, '<td valign="top">The lines make this work well. Very inviting and you''ve done a great job in not letting the lights become blown out.</td>', 'The lines make this work well. Very inviting and you''ve done a great job in not letting the lights become blown out.', '2008-12-29 10:23:06.000000', NULL, 1),
(5156226, 748735, 63244, '<td valign="top">I hate yellow retail lights! Cute perspective. I like the natural diagonal lines on the window and again on the floor.</td>', 'I hate yellow retail lights! Cute perspective. I like the natural diagonal lines on the window and again on the floor.', '2008-12-29 10:24:36.000000', NULL, 1),
(5156231, 749631, 63244, '<td valign="top">I find the red dress more interesting, yet the title implies the wedding dress is the main focus. :) Perhaps a different angle or choose just one of the dress windows. I first see the doorway, then the dresses. 5</td>', 'I find the red dress more interesting, yet the title implies the wedding dress is the main focus. :) Perhaps a different angle or choose just one of the dress windows. I first see the doorway, then the dresses. 5', '2008-12-29 10:27:19.000000', NULL, 1),
(5156237, 749496, 63244, '<td valign="top">I don''t like the pole down the middle, yet it adds something. Very interesting shot. Love the lighting and the focus. Border works very well!</td>', 'I don''t like the pole down the middle, yet it adds something. Very interesting shot. Love the lighting and the focus. Border works very well!', '2008-12-29 10:28:59.000000', NULL, 1),
(5156239, 748904, 63244, '<td valign="top">Cute shot. I like the sepia. Border is totally unnecessary IMO.</td>', 'Cute shot. I like the sepia. Border is totally unnecessary IMO.', '2008-12-29 10:29:38.000000', NULL, 1),
(5156241, 748906, 63244, '<td valign="top">Aw, how cute! love this in B&amp;W. Border actually adds. Nice tonal range and great detail.</td>', 'Aw, how cute! love this in B&W. Border actually adds. Nice tonal range and great detail.', '2008-12-29 10:30:28.000000', NULL, 1),
(5156243, 749280, 101682, '<td valign="top">The look every parent wants to see.</td>', 'The look every parent wants to see.', '2008-12-29 10:30:34.000000', NULL, 1),
(5156244, 748377, 63244, '<td valign="top">For some reason this made me laugh. Very whimsical shot!</td>', 'For some reason this made me laugh. Very whimsical shot!', '2008-12-29 10:31:12.000000', NULL, 1),
(5156249, 749415, 63244, '<td valign="top">This is just blah to me. Sorry.  Your detail and focus are sharp, but jacket looks a bit blown out. Perhaps crop the bottom third off? Sidewalk, shoes and below the window are not adding to this IMO.</td>', 'This is just blah to me. Sorry.  Your detail and focus are sharp, but jacket looks a bit blown out. Perhaps crop the bottom third off? Sidewalk, shoes and below the window are not adding to this IMO.', '2008-12-29 10:33:50.000000', NULL, 1),
(5156254, 748752, 63244, '<td valign="top">The silhouette works fab for this shot! Great composition and I like the color tones.  Well done!</td>', 'The silhouette works fab for this shot! Great composition and I like the color tones.  Well done!', '2008-12-29 10:34:21.000000', NULL, 1),
(5156256, 749649, 63244, '<td valign="top">B&amp;W is definitely the choice for this. Nice use of lines!</td>', 'B&W is definitely the choice for this. Nice use of lines!', '2008-12-29 10:35:15.000000', NULL, 1),
(5156258, 748895, 63244, '<td valign="top">SHOES!</td>', 'SHOES!', '2008-12-29 10:36:37.000000', NULL, 1),
(5156259, 749397, 63244, '<td valign="top">This made me chuckle! B&amp;W works. (Perhaps try to better line up the right side next time. ;} )</td>', 'This made me chuckle! B&W works. (Perhaps try to better line up the right side next time. ;} )', '2008-12-29 10:37:49.000000', NULL, 1),
(5156262, 749012, 63244, '<td valign="top">This is very nice! Love the ice on the windows. It give the shot a totally different feel.</td>', 'This is very nice! Love the ice on the windows. It give the shot a totally different feel.', '2008-12-29 10:39:58.000000', NULL, 1),
(5156265, 748637, 63244, '<td valign="top">Heehee...I see your flash reflection.This is interesting. Love the window items, but very hard to see with the blinds. Perhaps shorten your DOF to somewhat blur the blinds and the woman out front. Nice idea, definitely.</td>', 'Heehee...I see your flash reflection.This is interesting. Love the window items, but very hard to see with the blinds. Perhaps shorten your DOF to somewhat blur the blinds and the woman out front. Nice idea, definitely.', '2008-12-29 10:41:58.000000', NULL, 1),
(5156267, 749007, 63244, '<td valign="top">Cute! Like how the lollipops frame this on the right.</td>', 'Cute! Like how the lollipops frame this on the right.', '2008-12-29 10:42:47.000000', NULL, 1),
(5156269, 749280, 63244, '<td valign="top">How sweet! Great composition.</td>', 'How sweet! Great composition.', '2008-12-29 10:43:20.000000', NULL, 1),
(5156270, 749545, 63244, '<td valign="top">At least get out of the car...........</td>', 'At least get out of the car...........', '2008-12-29 10:43:49.000000', NULL, 1),
(5156272, 748362, 63244, '<td valign="top">Wonder how many people will think this is a real person, lol! Great job!</td>', 'Wonder how many people will think this is a real person, lol! Great job!', '2008-12-29 10:47:20.000000', NULL, 1),
(5156274, 749655, 63244, '<td valign="top">Cute find! Love the window frame!</td>', 'Cute find! Love the window frame!', '2008-12-29 10:48:26.000000', NULL, 1),
(5156497, 749593, 52549, '<td valign="top">Very "olde worlde" and very pretty.</td>', 'Very "olde worlde" and very pretty.', '2008-12-29 13:45:08.000000', NULL, 1),
(5156500, 749636, 52549, '<td valign="top">Lovely and very detailed.</td>', 'Lovely and very detailed.', '2008-12-29 13:47:22.000000', NULL, 1),
(5156502, 748904, 52549, '<td valign="top">Wonderful image, my favourite so far. Good luck.</td>', 'Wonderful image, my favourite so far. Good luck.', '2008-12-29 13:48:07.000000', NULL, 1),
(5156506, 749442, 52549, '<td valign="top">Could be a picture in a magazine. Very good indeed.</td>', 'Could be a picture in a magazine. Very good indeed.', '2008-12-29 13:50:15.000000', NULL, 1),
(5156507, 749452, 52549, '<td valign="top">I love this, it''s fascinating.</td>', 'I love this, it''s fascinating.', '2008-12-29 13:51:16.000000', NULL, 1),
(5156508, 749649, 52549, '<td valign="top">Difficult lighting situation. You handled it VERY well.</td>', 'Difficult lighting situation. You handled it VERY well.', '2008-12-29 13:52:46.000000', NULL, 1),
(5156513, 749272, 52549, '<td valign="top">I''ll be interested in seeing who did this image. The title is fantastic and the image has a comic flavour. Super!</td>', 'I''ll be interested in seeing who did this image. The title is fantastic and the image has a comic flavour. Super!', '2008-12-29 13:54:33.000000', NULL, 1),
(5156516, 748379, 52549, '<td valign="top">Wonderful blues and a fantastic perspective.</td>', 'Wonderful blues and a fantastic perspective.', '2008-12-29 13:56:03.000000', NULL, 1),
(5156517, 748542, 52549, '<td valign="top">Very busy looking but the colors are wonderful</td>', 'Very busy looking but the colors are wonderful', '2008-12-29 13:56:27.000000', NULL, 1),
