(5159371, 749280, 82749, '<td valign="top">Very cute, great expression on her face.  Congrats on the ribbon.</td>', 'Very cute, great expression on her face.  Congrats on the ribbon.', '2008-12-31 05:12:52.000000', NULL, 0),
(5159378, 749007, 100495, '<td valign="top">Did better than expected.  I''d waited for an hour outside a very pretty chocolate shop for the light to be right but it just never happened.  In the end I grabbed my niece for this set-up shot and tried to hide myself in her highlight. The reflection detail was largely luck.<br/> <br/>Hand-held in a busy shop as I was very rushed.<br/> <br/>Thanks for the comments.</td>', 'Did better than expected.  I''d waited for an hour outside a very pretty chocolate shop for the light to be right but it just never happened.  In the end I grabbed my niece for this set-up shot and tried to hide myself in her highlight. The reflection detail was largely luck. Hand-held in a busy shop as I was very rushed. Thanks for the comments.', '2008-12-31 05:14:37.000000', NULL, 0),
(5159384, 749423, 67363, '<td valign="top">Congratulation on a beautiful photo. I thought it would be a winner!</td>', 'Congratulation on a beautiful photo. I thought it would be a winner!', '2008-12-31 05:33:36.000000', NULL, 0),
(5159387, 748259, 67363, '<td valign="top">Congratulations! Well- deserved ribbon</td>', 'Congratulations! Well- deserved ribbon', '2008-12-31 05:35:46.000000', NULL, 0),
